# frozen_string_literal: true

RSpec.describe RuboCop::TodoPruner do
  subject(:pruned) do
    described_class.new(source).prune(entries) { |entry| offense_counts.fetch(entry.path) }
  end

  let(:offense_counts) { {} }

  def entry(cop_name, path)
    RuboCop::TodoAudit::Entry.new(cop_name, path)
  end

  context 'when sections in the middle and at the end lose all their entries' do
    let(:source) do
      <<~YAML
        # This configuration was generated by
        # `rubocop --auto-gen-config`

        # Offense count: 1
        Style/ClassVars:
          Exclude:
            - 'a.rb'

        # Offense count: 1
        # This cop supports safe autocorrection (--autocorrect).
        Style/StringLiterals:
          Exclude:
            - 'b.rb'

        # Offense count: 1
        Lint/UselessAssignment:
          Exclude:
            - 'c.rb'

        # Offense count: 1
        Naming/FileName:
          Exclude:
            - 'd.rb'
      YAML
    end
    let(:entries) do
      [entry('Style/StringLiterals', 'b.rb'), entry('Naming/FileName', 'd.rb')]
    end

    it 'removes the sections with their comments and separators' do
      expect(pruned).to eq(<<~YAML)
        # This configuration was generated by
        # `rubocop --auto-gen-config`

        # Offense count: 1
        Style/ClassVars:
          Exclude:
            - 'a.rb'

        # Offense count: 1
        Lint/UselessAssignment:
          Exclude:
            - 'c.rb'
      YAML
    end
  end

  context 'when every section loses all its entries' do
    let(:source) do
      <<~YAML
        # This configuration was generated by
        # `rubocop --auto-gen-config`

        # Offense count: 1
        Style/ClassVars:
          Exclude:
            - 'a.rb'

        # Offense count: 1
        Style/StringLiterals:
          Exclude:
            - 'b.rb'
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb'), entry('Style/StringLiterals', 'b.rb')] }

    it 'keeps only the header comment' do
      expect(pruned).to eq(<<~YAML)
        # This configuration was generated by
        # `rubocop --auto-gen-config`
      YAML
    end
  end

  context 'when a section keeps some entries' do
    let(:source) do
      <<~YAML
        # Offense count: 6
        Style/ClassVars:
          Exclude:
            - 'a.rb'
            - b.rb
            - "c.rb"
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'b.rb')] }
    let(:offense_counts) { { 'a.rb' => 2, 'c.rb' => 3 } }

    it 'removes the entries in any quoting style and updates the offense count' do
      expect(pruned).to eq(<<~YAML)
        # Offense count: 5
        Style/ClassVars:
          Exclude:
            - 'a.rb'
            - "c.rb"
      YAML
    end
  end

  context 'when a kept entry is a glob or a regexp' do
    let(:source) do
      <<~YAML
        # Offense count: 6
        Style/ClassVars:
          Exclude:
            - 'a.rb'
            - 'lib/**/*.rb'
            - !ruby/regexp /spec/
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb')] }

    it 'does not update the offense count' do
      expect(pruned).to eq(<<~YAML)
        # Offense count: 6
        Style/ClassVars:
          Exclude:
            - 'lib/**/*.rb'
            - !ruby/regexp /spec/
      YAML
    end
  end

  context 'when a file is listed twice' do
    let(:source) do
      <<~YAML
        Style/ClassVars:
          Exclude:
            - 'a.rb'
            - 'b.rb'
            - 'a.rb'
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb')] }

    it 'removes both items' do
      expect(pruned).to eq(<<~YAML)
        Style/ClassVars:
          Exclude:
            - 'b.rb'
      YAML
    end
  end

  context 'when a section has other settings' do
    let(:source) do
      <<~YAML
        # Offense count: 1
        Style/ClassVars:
          Enabled: true
          Exclude:
            - 'a.rb'
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb')] }

    it 'removes only the `Exclude` setting' do
      expect(pruned).to eq(<<~YAML)
        # Offense count: 1
        Style/ClassVars:
          Enabled: true
      YAML
    end
  end

  context 'when the entries cannot be removed line by line' do
    let(:source) do
      <<~YAML
        Style/ClassVars:
          Exclude: ['a.rb', 'b.rb']
        Style/StringLiterals:
          Exclude:
            - 'a.rb'
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb'), entry('Style/StringLiterals', 'a.rb')] }

    it 'returns nil' do
      expect(pruned).to be_nil
    end
  end

  context 'when removing the entries would leave an empty cop section' do
    let(:source) do
      <<~YAML
        Style/ClassVars:
          # Remove when the legacy code is gone.
          Exclude:
            - 'a.rb'
      YAML
    end
    let(:entries) { [entry('Style/ClassVars', 'a.rb')] }

    it 'returns nil' do
      expect(pruned).to be_nil
    end
  end
end
